-- Additive catalog sample collected with REA from the public ICONDENIM collection listing.
-- Source snapshot: https://icondenim.com/collections/all, pages 1-12 (2026-11-23 Asia/Saigon).
-- 360 listing cards contain 358 unique product names; duplicate titles are merged by color.
-- Names, displayed prices, promotion prices, colors and images are storefront data.
-- Size/stock/description are local/demo test values. Price ranges use the lowest listed price.
-- This file adds only missing records and a missing "Set đồ" category; it never deletes or updates rows.
-- Run with psql only. Do not use on production.

\set spring_profiles_active ''
\getenv spring_profiles_active SPRING_PROFILES_ACTIVE
SELECT coalesce(bool_or(lower(btrim(profile)) = 'prod'), false) AS active_prod
FROM regexp_split_to_table(:'spring_profiles_active', ',') AS profiles(profile)
\gset
\if :active_prod
\echo Refusing to load demo products while SPRING_PROFILES_ACTIVE includes prod.
DO $$ BEGIN RAISE EXCEPTION 'Demo product seed is disabled for the prod profile.'; END $$;
\quit
\endif

BEGIN;

INSERT INTO categories(name)
SELECT 'Set đồ'
WHERE NOT EXISTS (SELECT 1 FROM categories category WHERE lower(category.name) = lower('Set đồ'));

