INSERT INTO products(
    category_id, name, color, size, price, sale_price, quantity_remaining, gender,
    description, material, image_url, color_images, badge, featured, active
)
SELECT category.category_id, seed.name, seed.colors, seed.sizes, seed.price, seed.sale_price,
       seed.stock, 'NAM',
       'Mẫu tham khảo từ danh mục công khai ICONDENIM; size và tồn kho là dữ liệu kiểm thử.',
       NULL, seed.image_url, seed.color_images, NULL, FALSE, TRUE
FROM seed
JOIN categories category ON category.name = seed.category_name
WHERE NOT EXISTS (
    SELECT 1 FROM products existing WHERE lower(existing.name) = lower(seed.name)
);

SELECT category.name AS loai_san_pham, COUNT(*) AS tong_san_pham
FROM products product
JOIN categories category ON category.category_id = product.category_id
GROUP BY category.name
ORDER BY category.name;

COMMIT;
